window.renderServiceGuide=(t,href)=>`<section class="project-header"><div class="project-title"><h1 class="page-title">${t('中远海运港口<br>服务号功能焕新传播','COSCO SHIPPING Ports<br>Service account communication')}</h1></div><div class="project-info"><dl><div><dt>${t('项目 / 品牌','Project / Brand')}</dt><dd>${t('中远海运港口','COSCO SHIPPING Ports')}</dd></div><div><dt>${t('项目形式','Format')}</dt><dd>${t('公众号功能推广长图','WeChat service guide')}</dd></div><div><dt>${t('服务类别','Category')}</dt><dd>${t('新媒体传播与内容创意','Digital & Social Content')}</dd></div><div><dt>${t('服务内容','Services')}</dt><dd>${t('信息梳理 / 长图视觉 / 动态演示','Information design / Editorial visuals / Motion demonstration')}</dd></div></dl><div class="project-description"><span class="number">${t('项目介绍','About the project')}</span><p>${t('以全球航运网络为视觉线索，将业务资讯、码头地图与服务入口串联成直观的功能导览。通过界面展示、功能标注和动态演示，让服务号的使用方式更清晰。','A visual guide connecting business updates, terminal maps and service entry points through the language of global shipping. Interface imagery, annotations and motion demonstrations make the service easier to understand.')}</p></div></div></section><section class="guide-preview"><div class="annual-device"><div class="annual-status" aria-hidden="true"><i class="annual-island"></i></div><iframe class="guide-original-frame" src="assets/service-guide/original.html?v=tail-trim-2" title="${t('原作点击交互预览','Original interactive artwork')}" sandbox="allow-scripts allow-same-origin"></iframe></div><div class="guide-preview-note"><p>${t('在手机内上下滚动，查看完整作品。','Scroll inside the phone to read the artwork.')}</p><div class="guide-reader-actions"><button data-guide-expand>${t('展开阅读 ↗','Expand ↗')}</button><button data-guide-restart>${t('重新体验','Restart')}</button><button data-guide-top>${t('回到开头 ↑','Back to top ↑')}</button></div><progress class="guide-read-progress" max="100" value="0" aria-label="${t('阅读进度','Reading progress')}"></progress><span data-guide-percent>0%</span></div></section><dialog class="guide-full-reader"><button data-guide-close aria-label="${t('关闭','Close')}">×</button><iframe class="guide-full-original" title="${t('展开原作','Expanded original')}" sandbox="allow-scripts allow-same-origin"></iframe></dialog><section class="guide-hero"><img src="assets/service-guide/0.webp" alt="${t('优质服务 即刻启程','Quality service, ready to sail')}"><div><span>SERVICE / CONNECTED PORTS</span><h2>${t('点击互动，<br>展开服务号三大特点。','Click to explore.<br>Three service highlights.')}</h2><p>${t('通过互动点击逐步展开“更新的业务资讯、更全的功能接口、更优的服务体验”三个主要特点，<br>让用户在主动探索中了解服务号的功能与价值。','Click interactions progressively reveal three key highlights: up-to-date business information, more comprehensive service access and a better service experience, inviting users to actively explore the account’s features and value.')}</p></div></section><section class="guide-thinking">${[['01','更新的业务资讯','Up-to-date business information','点击展开业务资讯，<br>直观了解更新内容。','Layered interfaces highlight the path to business updates.'],['02','更全的功能接口','More comprehensive service access','点击查看功能接口，<br>连接码头地图与服务。','Maps and annotations explain service coverage and usage.'],['03','更优的服务体验','A better service experience','互动展示产品服务，<br>了解 e-Port 使用场景。','Product and e-Port entry points connect the guide to practical use.']].map(([n,z,e,d,de])=>`<article><h3>${t(z,e)}</h3><p>${t(d,de)}</p><img class="guide-feature-image" src="assets/service-guide/${n==='01'?'feature-news.webp':n==='02'?'3.webp':'5.webp'}" alt="${t(z,e)}" loading="lazy"></article>`).join('')}</section><section class="guide-motion"><div><span>GLOBAL TERMINALS / MOTION</span><h2>${t('点亮全球码头','Global terminals, illuminated')}</h2><p>${t('通过原作地图动图，展示全球码头布局的视觉表达。','The original animation demonstrates the global terminal network.')}</p></div><img id="guide-map" src="assets/service-guide/map.gif" alt="${t('全球码头布局动态演示','Global terminal network demonstration')}"></section><section class="guide-qr-footer"><div class="guide-qr" style="border:0;padding:0"><img src="assets/service-guide/wechat-qr.png" alt="${t('扫码查看服务号使用攻略原文','Scan to view the original WeChat article')}" style="display:block;width:100%;height:100%;object-fit:contain;border-radius:0"></div><p>${t('扫一扫，在公众号浏览','Scan to view on WeChat')}</p></section><section class="next-project"><a href="${href('work')}">${t('返回全部案例','Back to all projects')}</a><a href="${href('project','&id=nationalday')}">${t('中远海运港口 · 国庆主题传播','COSCO SHIPPING Ports · National Day')}</a></section>`;
document.addEventListener('DOMContentLoaded',()=>{const b=document.querySelector('[data-guide-play]');if(!b)return;let playing=false;b.addEventListener('click',()=>{playing=!playing;document.querySelector('#guide-map').src='assets/service-guide/'+(playing?'map.gif':'map-poster.webp');b.textContent=document.documentElement.lang==='en'?(playing?'Stop demonstration':'Play demonstration'):(playing?'停止演示':'播放动态演示')})});
document.addEventListener('DOMContentLoaded',()=>{const f=document.querySelector('.guide-original-frame');if(!f)return;const dialog=document.querySelector('.guide-full-reader'),full=dialog.querySelector('iframe');document.querySelector('[data-guide-top]').addEventListener('click',()=>f.contentWindow.postMessage({type:'guide-original-top'},location.origin));document.querySelector('[data-guide-restart]').addEventListener('click',()=>f.contentWindow.postMessage({type:'guide-original-restart'},location.origin));document.querySelector('[data-guide-expand]').addEventListener('click',()=>{full.src=f.src;dialog.showModal()});document.querySelector('[data-guide-close]').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>full.src='about:blank');addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==f.contentWindow||e.data?.type!=='guide-original-progress')return;document.querySelector('.guide-read-progress').value=e.data.value;document.querySelector('[data-guide-percent]').textContent=e.data.value+'%'})});
